import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtemp, writeFile, readFile, readdir, rm} from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import {decodeWav, encodeWav, joinWav, MAX_AUDIO_BYTES, RATE} from '../lib/audio.js';
import {normalizeFishWav} from '../lib/fish-wav.js';
import {FishProvider} from '../lib/fish.js';
import {VoiceStudio} from '../lib/service.js';

// Generated bytes only. Never read or embed private reference/response samples.
function wav(frames=4410) {
  const pcm=Buffer.alloc(frames*2);
  for(let i=0;i<frames;i++)pcm.writeInt16LE(Math.round(3000*Math.sin(i*0.1)),i*2);
  return encodeWav(pcm);
}
function fishHeader(b=wav()) {
  const copy=Buffer.from(b);copy.writeUInt32LE(0xffffff24,4);copy.writeUInt32LE(0xffffff00,40);return copy;
}
function chunk(id, data, padded=true) {
  const b=Buffer.alloc(8+data.length+(padded?data.length%2:0));
  b.write(id);b.writeUInt32LE(data.length,4);data.copy(b,8);return b;
}
const fmt=()=>wav().subarray(12,36), data=()=>chunk('data',Buffer.alloc(8));
function riff(chunks) {
  const b=Buffer.concat([Buffer.from('RIFF\0\0\0\0WAVE'),...chunks]);b.writeUInt32LE(b.length-8,4);return b;
}
const config={fishApiKey:'synthetic-test-key',timeoutMs:1000};
const input={text:'Synthetic test.',referenceId:'synthetic-voice'};
function streamResponse(b, cuts=[1,7,13,35,43,47]) {
  let offset=0,index=0;
  return new Response(new ReadableStream({pull(controller){
    if(offset===b.length){controller.close();return;}
    const end=Math.min(b.length,cuts[index++]??b.length);
    controller.enqueue(b.subarray(offset,end));offset=end;
  }}));
}
async function fixture(t) {
  const root=await mkdtemp(path.join(os.tmpdir(),'dsh-fish-wav-'));
  t.after(async()=>{
    assert.equal(path.dirname(path.resolve(root)),path.resolve(os.tmpdir()));
    await rm(root,{recursive:true,force:true});
  });
  const configFile=path.join(root,'config.json');
  await writeFile(configFile,JSON.stringify({...config,rightsConfirmed:true,allowPaidRequests:true,allowReferenceUpload:true,defaultReferenceId:'synthetic-voice'}));
  return {root,configFile};
}

test('finite WAV and finite ancillary/trailing chunks remain byte-identical',()=>{
  for(const b of [wav(),riff([chunk('JUNK',Buffer.from('data!')),fmt(),data(),chunk('LIST',Buffer.from('test'))])]) {
    const out=normalizeFishWav(b);assert.deepEqual(out,b);assert.notEqual(out,b);decodeWav(out);
  }
});
test('known Fish pair becomes a finite WAV; only size fields change, input/PCM stay intact',()=>{
  const b=fishHeader(),original=Buffer.from(b);
  assert.throws(()=>decodeWav(b),{code:'INVALID_AUDIO'});
  const out=normalizeFishWav(b);assert.deepEqual(b,original);assert.deepEqual(out.subarray(44),b.subarray(44));
  assert.equal(out.readUInt32LE(4),out.length-8);assert.equal(out.readUInt32LE(40),out.length-44);
  for(let i=0;i<b.length;i++)if(!(i>=4&&i<8)&&!(i>=40&&i<44))assert.equal(out[i],b[i]);
  assert.equal(decodeWav(out).duration,.1);
});
test('unknown or mismatched sentinel pairs and ordinary oversized declarations are rejected',()=>{
  for(const [riffSize,dataSize] of [[0xffffffff,0xffffffff],[0xffffff24,0xffffffff],[0xffffffff,0xffffff00],[90000,89964],[0xffffff24,8820],[8856,0xffffff00]]) {
    const b=wav();b.writeUInt32LE(riffSize,4);b.writeUInt32LE(dataSize,40);
    assert.throws(()=>normalizeFishWav(b),{code:'INVALID_AUDIO'});
  }
});
test('Fish special case refuses every changed canonical header field',()=>{
  for(const offset of [0,8,12,16,20,22,24,28,32,34,36]) {
    const b=fishHeader();b[offset]^=1;assert.throws(()=>normalizeFishWav(b),{code:'INVALID_AUDIO'});
  }
  // A valid but different sample rate is not part of the placeholder contract.
  const b=fishHeader();b.writeUInt32LE(24000,24);b.writeUInt32LE(48000,28);
  assert.throws(()=>normalizeFishWav(b),{code:'INVALID_AUDIO'});
});
test('non-bytes, oversized bodies, short header, empty and odd PCM are rejected',()=>{
  for(const b of [new ArrayBuffer(44),Buffer.alloc(MAX_AUDIO_BYTES+1),fishHeader().subarray(0,43),fishHeader().subarray(0,45)])assert.throws(()=>normalizeFishWav(b),{code:'INVALID_AUDIO'});
  assert.throws(()=>normalizeFishWav(fishHeader().subarray(0,44)),{code:'EMPTY_AUDIO'});
});
test('fake data in pre-data JUNK is never searched; noncanonical placeholder layout rejected',()=>{
  const b=riff([chunk('JUNK',Buffer.from('data\0\0\0\0')),fmt(),data()]);
  b.writeUInt32LE(0xffffff24,4);
  assert.throws(()=>normalizeFishWav(b),{code:'INVALID_AUDIO'});
});
test('data byte pattern inside PCM is preserved instead of parsed as a chunk',()=>{
  const b=fishHeader();Buffer.from('data\xff\xff\xff\xff').copy(b,60);
  assert.deepEqual(normalizeFishWav(b).subarray(44),b.subarray(44));
});
test('RF64 and high-bit aliases of RIFF/WAVE/chunk identifiers are not silently accepted',()=>{
  const rf64=fishHeader();rf64.write('RF64');assert.throws(()=>normalizeFishWav(rf64));
  for(const offset of [0,8,12,36]){const b=wav();b[offset]|=128;assert.throws(()=>decodeWav(b));assert.throws(()=>normalizeFishWav(b));}
});
test('strict parser rejects missing/duplicate fmt or data and malformed fmt',()=>{
  for(const chunks of [[fmt(),fmt(),data()],[fmt(),data(),data()],[fmt(),chunk('JUNK',Buffer.alloc(8))],[data(),chunk('JUNK',Buffer.alloc(32))],[chunk('fmt ',Buffer.alloc(15)),data()],[chunk('fmt ',Buffer.alloc(16)),data()]]) {
    const b=riff(chunks);assert.throws(()=>decodeWav(b));assert.throws(()=>normalizeFishWav(b));
  }
});
test('strict parser accepts required odd padding, rejects missing padding and partial headers',()=>{
  const good=riff([fmt(),data(),chunk('JUNK',Buffer.from([1]))]);decodeWav(good);
  for(const tail of [chunk('JUNK',Buffer.from([1]),false),Buffer.from('JUNK'),Buffer.from([1])]) {
    const b=riff([fmt(),data(),tail]);assert.throws(()=>decodeWav(b),{code:'INVALID_AUDIO'});
  }
});
test('ordinary aligned and unaligned truncation stays rejected; unknown sizes never repaired',()=>{
  for(const n of [1,2,4,100])assert.throws(()=>normalizeFishWav(wav().subarray(0,wav().length-n)),{code:'INVALID_AUDIO'});
});
test('Fish PCM misalignment is rejected; aligned clean EOF cannot prove semantic completion',()=>{
  const b=fishHeader();assert.throws(()=>normalizeFishWav(b.subarray(0,b.length-1)),{code:'INVALID_AUDIO'});
  // Document the unavoidable limit: without finite sizes, even an aligned early
  // EOF is structurally indistinguishable from a shorter completed response.
  const out=normalizeFishWav(b.subarray(0,b.length-2));assert.equal(decodeWav(out).frames,4409);
});
test('Fish EOF contract cannot distinguish metadata-like PCM from actual trailing metadata',()=>{
  const b=Buffer.concat([fishHeader(),chunk('LIST',Buffer.from('test'))]);
  const out=normalizeFishWav(b);assert.deepEqual(out.subarray(44),b.subarray(44));
  // No heuristic scan/strip that could destroy legitimate PCM containing LIST.
});
test('finite chunks with unaligned PCM or an overrun stay rejected',()=>{
  assert.throws(()=>normalizeFishWav(riff([fmt(),chunk('data',Buffer.alloc(3))])));
  const b=wav();b.writeUInt32LE(b.length,40);assert.throws(()=>normalizeFishWav(b),{code:'INVALID_AUDIO'});
});
test('provider collects arbitrarily split HTTP chunks before adapting Fish header',async()=>{
  const b=fishHeader();let calls=0;
  const p=new FishProvider(config,async()=>{calls++;return streamResponse(b);});
  const out=await p.generate(input);assert.equal(calls,1);assert.equal(decodeWav(out).duration,.1);assert.deepEqual(out.subarray(44),b.subarray(44));
});
test('mid-body transport error returns no partial WAV and never retries paid POST',async()=>{
  let calls=0,pulls=0;
  const p=new FishProvider(config,async()=>{calls++;return new Response(new ReadableStream({pull(controller){if(pulls++===0)controller.enqueue(fishHeader().subarray(0,100));else controller.error(Error('synthetic disconnect'));}}));});
  await assert.rejects(p.generate(input),{code:'FISH_NETWORK_ERROR'});assert.equal(calls,1);
});
test('mid-body cancellation never turns a partial body into a completed WAV',async()=>{
  const ac=new AbortController();let calls=0,pulls=0;
  const p=new FishProvider(config,async()=>{calls++;return new Response(new ReadableStream({pull(controller){if(pulls++===0)controller.enqueue(fishHeader().subarray(0,100));else{ac.abort();controller.error(ac.signal.reason);}}}));});
  await assert.rejects(p.generate(input,ac.signal),{name:'AbortError'});assert.equal(calls,1);
});
test('adapted segments retain exact added silence through joinWav',()=>{
  const a=normalizeFishWav(fishHeader()),result=joinWav([{audio:a,pause_after_ms:2000},{audio:a}]),decoded=decodeWav(result.bytes);
  assert.equal(result.duration,2.2);assert.deepEqual(result.silences,[{start_frame:4410,frames:88200}]);
  assert(decoded.pcm.subarray(4410*2,92610*2).every(v=>v===0));
});
test('real provider/service path recovers after malformed and disconnected responses; repeated generation saves WAV',async t=>{
  const f=await fixture(t);let calls=0;
  const fetcher=async()=>{
    calls++;
    if(calls===1)return new Response(wav().subarray(0,100));
    if(calls===2)return new Response(new ReadableStream({start(c){c.error(Error('synthetic disconnect'));}}));
    return streamResponse(fishHeader());
  };
  const service=new VoiceStudio({configFile:f.configFile,providerFactory:c=>new FishProvider(c,fetcher)});
  const args={text:'First.Second.',segments:[{text:'First.'},{text:'Second.',pause_before_ms:2000}],output_name:'synthetic'};
  for(const code of ['INVALID_AUDIO','FISH_NETWORK_ERROR']){
    const result=await service.generate(args,{cwd:f.root});assert.equal(result.error_code,code);assert.equal(result.completed_segments,0);assert.equal(service.busy,false);
    assert(!(await readdir(f.root)).includes('generated_audio'));
  }
  const first=await service.generate(args,{cwd:f.root}),second=await service.generate(args,{cwd:f.root});
  assert(first.success,JSON.stringify(first));assert(second.success,JSON.stringify(second));assert.notEqual(first.file_path,second.file_path);
  assert.equal(decodeWav(await readFile(first.file_path)).duration,2.2);assert.equal(calls,6);
});
test('reference import keeps strict validation and cannot use Fish response compatibility',async t=>{
  const f=await fixture(t),reference=path.join(f.root,'synthetic.wav');await writeFile(reference,fishHeader(wav(RATE*3)));
  let calls=0;const service=new VoiceStudio({configFile:f.configFile,providerFactory:()=>{calls++;throw Error('Must not upload');}});
  const result=await service.create({name:'Synthetic',path:reference});assert.equal(result.error_code,'INVALID_AUDIO');assert.equal(calls,0);
});
